from pathlib import Path
R=Path(__file__).parent
INPUT=Path('/dev/shm/informatics-q2-implementation-20261107/shared-author-input.json')
assert hashlib.sha256(INPUT.read_bytes()).hexdigest()=='4cc15cc59ada804de389b10b1a6c381d22690eba70857df8748eaada48944002'
X=json.loads(INPUT.read_text()); G=X['exactGoals']; TASKS={}
def add(prefix,task,solution,criteria,materials=()):
 ids=[i for i in G if i.startswith(prefix)];assert len(ids)==1,(prefix,ids)
 gid=ids[0];anchor='T'+str(len(TASKS)+1).zfill(2)
 TASKS[gid]={'id':anchor,'goalId':gid,'fullGoalDescription':G[gid]['description'],'title':G[gid]['title'],'task':task,'solution':solution,'materials':list(materials),'essentialCriteria':[{'id':anchor+'-C'+str(n+1),'description':v,'points':1} for n,v in enumerate(criteria)]}
M={}
M['MODEL']='''M1 – Unabhängiger Modellierungsauftrag: Das Reparaturcafé WerkzeugWelt speichert Mitglied(MitgliedNr,Name), Gerät(SerienNr,Bezeichnung), Standort(StandortNr,Name) und Ausleihe. Jedes Gerät steht an genau einem Standort, ein Standort kann leer sein. Ein Mitglied kann null oder viele Geräte ausleihen; ein Gerät kann über die Zeit null oder viele Ausleihen haben. Jede Ausleihe hat eine global eindeutige AusleihNr, genau ein Mitglied, genau ein Gerät, ein Startdatum und ein noch fehlendes Rückgabedatum. Wiederholte Ausleihen desselben Geräts durch dasselbe Mitglied sind erlaubt, auch am gleichen Tag. Für ein Gerät darf zeitgleich höchstens eine Ausleihe offen sein. Nur Geräte und Mitglieder mit Ausleihe zu speichern wäre falsch. Mitgliedsnamen und Standortnamen sind nicht eindeutig. Modellieren Sie genau diese Welt, nicht das separate M2-Kursschema. Weitere Daten werden nicht vorausgesetzt.'''
M['DB']='''M2 – Vollständige SQL-Fixture LeihZeit (eigener Kursanbieter). Alle IDs sind INTEGER, alle Texte TEXT. NOT NULL gilt für alle Spalten außer Kurs.rid; Preis in ganzen EUR, Kapazität positiv, Preis>=0. Person(pid PK,pseudonym,ort); Team(tid PK,name); Raum(rid PK,name); Kurs(kid PK,titel,preis,maxPlaetze,tid FK->Team,rid NULL FK->Raum); Buchung(pid FK->Person,kid FK->Kurs,status CHECK IN ('aktiv','storniert'),PK(pid,kid)). Pro Person/Kurs gibt es höchstens einen aktuellen Satz, keinen Zwang zur Buchung jedes Paares. Kontakt(pid PK/FK->Person,email). Texte vergleichen binär; Pseudonyme sind nicht eindeutig. SQL hat Mehrmengen, RA hat Mengen; SQL benötigt DISTINCT für mengenwertige Projektion. Jede Aufgabe startet neu bei diesen Daten, sofern ihr eigener Zustand ausdrücklich fortgesetzt wird. Sortierung nur wo verlangt, bei Gleichstand zusätzlich kid bzw.pid aufsteigend. NULL ist kein leerer Text.
Person(pid,pseudonym,ort)={(1,'ada','Kassel'),(2,'ben','Kassel'),(3,'cora','Fulda'),(4,'dino','Marburg'),(5,'eva','Fulda')}.
Team(tid,name)={(1,'Werkstatt'),(2,'Offene Medien'),(3,'Archiv')}; Raum(rid,name)={(1,'Nord'),(2,'Sued')}; Kontakt={(1,'ada@example.invalid'),(3,'cora@example.invalid')}.
Kurs(kid,titel,preis,maxPlaetze,tid,rid)={(10,'Fotobasis',20,3,1,1),(20,'Audiolabor',30,2,2,2),(30,'Videoschnitt',40,2,1,NULL),(40,'Datenschutz-Werkstatt',10,4,2,1),(50,'Archiv <offen>',15,2,3,NULL)}.
Buchung(pid,kid,status)={(1,10,'aktiv'),(2,10,'aktiv'),(3,10,'storniert'),(2,20,'aktiv'),(3,20,'aktiv'),(1,30,'aktiv'),(4,30,'aktiv'),(5,40,'aktiv'),(2,40,'storniert')}.
SQLite3 mit PRAGMA foreign_keys=ON ist die lokale Referenz. Gleichwertiges SQL ist erlaubt. Wenn eine Aufgabe ausdrücklich Rollenbefehle verlangt,gilt ihre mitgelieferte Rollenkarte;es wird keine SQLite-Rollenunterstützung behauptet.'''
M['ALG']='''M3 – Unabhängige Algebrafixture. R(a,x)={(1,'rot'),(2,'blau')}; S(b,y)={(10,'rot'),(20,'gruen')}; V(a,b)={(1,10),(1,20),(2,20)}. Keine NULL-Werte, keine weiteren Tupel. Gleicher Attributname bezeichnet dieselbe Domäne; x und y sind unterschiedlich benannt. Produkt/Join schreiben daher alle benannten Attribute aus; Theta-Join auf x=y. Relationen sind Mengen; Projektion entfernt Duplikate. In SQL entsprechen R(a INTEGER,x TEXT),S(b INTEGER,y TEXT),V(a INTEGER,b INTEGER) genau diesen Tupeln. R.a, S.b und V.(a,b) sind Primärschlüssel; V referenziert beide Schlüssel.'''
M['NORM']='''M4 – Normalisierungsfall mit wiederholten Gruppen. Export(pid,pseudonym,ort,buchungen) enthält (1,'ada','Kassel',[(10,'Fotobasis',20,1,'Werkstatt','aktiv'),(30,'Videoschnitt',40,1,'Werkstatt','aktiv')]), (2,'ben','Kassel',[(10,'Fotobasis',20,1,'Werkstatt','aktiv'),(20,'Audiolabor',30,2,'Offene Medien','aktiv')]). Ein Eintrag in buchungen hat (kid,titel,preis,tid,teamName,status). Nach Auflösung der Listen heißt die Relation E(pid,pseudonym,ort,kid,titel,preis,tid,teamName,status), Schlüssel(pid,kid); sämtliche nichttrivialen FDs folgen aus pid->pseudonym,ort; kid->titel,preis,tid; tid->teamName; (pid,kid)->status. Keine zusätzlichen FDs oder Mehrwertigkeitsabhängigkeiten werden angenommen.'''
M['ROLES']='''M5 – Lehrrollenmodell (keine Behauptung eines ausgeführten Rollenservers): Rollen auskunft und anmeldedienst existieren, niemand erbt Rechte von PUBLIC; auskunft hat versehentlich SELECT auf Person, sonst keine Rechte; anmeldedienst hat keine Rechte. Vorgaben: auskunft darf nur KursAuskunft(kid,titel,preis) lesen; anmeldedienst darf Buchung lesen/einfügen, sonst nichts; Eigentümer führt DDL/DML aus. Unterstützte Syntax: CREATE VIEW name AS SELECT ...; GRANT SELECT[,INSERT] ON object TO role; REVOKE SELECT ON object FROM role. Tabellenrechte gelten auf der genannten Tabelle, Sichtrechte erlauben nur die Sicht. Keine Rolle hat Eigentümer-/Superuserrechte. Rechtebeschreibungen und Rechtebefehle müssen zu dieser Matrix passen.'''
M['WEB']='''M6 – Gegebener lokaler API-Vertrag: sqlite3.connect(path), con.execute(sql,tuple) bindet ?-Werte; fetchall() liefert Tupelliste; commit() bestätigt Schreiben; close() schließt die Verbindung. SQL-Ausnahmen führen im lokalen Server zu kontrolliertem 500, keine Daten im Fehlertext; Schreibfehler werden rollback() zurückgesetzt. Gegebene sichere Hilfen (keine eigenständige Sicherheitsprüfung im 20er-Zielumfang): parse_qs(...,keep_blank_values=True); genau ein Wert, ASCII-Ziffern, höchstens vier Zeichen für maxPreis, 1..3 für page, Bereich maxPreis0..1000/page1..100; vor int() Länge prüfen. html.escape(str(value),quote=True) ist für HTML-Text und zitierte Attribute gegeben.
GET /kurse?maxPreis=30 liefert ALLE Kurszeilen mit preis<=30 nach kid. GET /seiten?page=1 liefert ALLE Kurse nach kid mit Seitengröße2, ohne Preisfilter. Die zwei Endpunkte sind alternative Leistungswege für T17, nicht kumulativ. Ungültige/fehlende/doppelte Parameter ergeben400; leere gültige Ergebnismenge200. POST /titel erwartet kid und titel; kid1..1000000, titel1..80Zeichen. Authentifizierte Lehrsitzung und CSRF-Prüfung dieses Endpunkts werden geliefert. Für Sicherheitsaufgaben zusätzlich POST /buchen mit kid und csrfToken='fixture-token'; pid=1 stammt nur aus gegebener Sitzung. Tokenfehler403, unbekannter kid404, vorhandene Buchung409, Erfolg201. Ein solcher Fixturetoken ist kein Produktivgeheimnis. POST ist weder Verschlüsselung noch Autorisierung.'''
M['LAW']='''M7 – Didaktische Normenkarte, amtlich am 07.11.2026 über EUR-Lex geöffnet und inhaltlich geprüft: DSGVO, Verordnung(EU)2016/679, Art.4Nr.1/5;5Abs.1b,c,e;6Abs.1a,b;7Abs.1–4;13Abs.1c/e,2a–c;21Abs.2/3;25Abs.1/2;32Abs.1. Aktueller Textzugang: https://eur-lex.europa.eu/legal-content/DE/TXT/?uri=CELEX:02016R0679-20160504 ; amtlicher Ausgangstext https://eur-lex.europa.eu/eli/reg/2016/679/oj/deu . Kurzfassung: Personenbezug umfasst indirekte Zuordnung; Pseudonymisierung hebt ihn nicht auf. Zweckbindung, Datenminimierung und begrenzte Speicherung gelten. Notwendige Vertragsverarbeitung kann Art.6Abs.1b tragen; getrennte freiwillige Werbung im vorliegenden Fall nutzt Einwilligung nach Art.6Abs.1a. Diese muss freiwillig, informiert, bestimmt und nachweisbar sein; Widerruf jederzeit, so einfach wie Erteilung. Über Zwecke, Grundlage, Empfänger, Speicherdauer und Rechte informieren. Gegen Direktwerbung besteht Widerspruchsrecht; nach Widerspruch diese Verarbeitung stoppen. Gestaltung/Voreinstellungen und angemessene Sicherheit schützen Daten. Das ist der begrenzte Normenausschnitt für erfundene erwachsene Vertragskunden, kein vollständiges Gutachten zu Werbekanälen oder nationalem Wettbewerbsrecht. Es wird ausschließlich der personenbezogene Verarbeitungszweck geprüft;weder Versand von E-Mail-Werbung noch Zulässigkeit nach UWG§7 wird beurteilt oder erlaubt. DSGVO-Einwilligung allein ist keine pauschale Versandzulässigkeit.
Fall: Nötige Buchungsdaten sichern die vereinbarte Kursleistung. Zusätzlich möchte Werbepartner AdCo verknüpfbare Klicks und freiwillige Kontaktadressen für eigene personalisierte Werbung; keine besonderen Kategorien, keine Minderjährigen. Ablehnen/Widerrufen hindert Buchung nicht; es ist kein anderer Werberechtsgrund im Fall vorgegeben. Pseudonyme lassen sich über pid/Kontakt zuordnen. Informationsselbstbestimmung ist die grundsätzlich geschützte Entscheidung über Preisgabe/Verwendung persönlicher Daten, kein voraussetzungsloses Verbot jeder gesetzlichen Verarbeitung.'''
M['SEC']='''M8 – Sicherheitsvorfälle: Alle Angestellten teilen ein Administratorkonto; eine Aushilfe liest unnötig Kontaktadressen. Jemand verändert maxPlaetze ohne Freigabe und Protokoll. Das einzige ungetestete Backup liegt auf demselben gestohlenen Notebook. Zudem wird eine nicht geprüfte E-Mail des vermeintlichen Kursleiters als echter Änderungsauftrag akzeptiert. Das letzte Szenario betrifft Authentizität. Verantwortliche Rollen sind Leitung, Administration und Datenverantwortliche. Maßnahmen dürfen verhältnismäßig sein; kein absoluter Schutz wird erwartet.'''
M['COMPLEX']='''M9 – Zusätzlicher komplexer ER-Fall zu M2: Kurs besitzt1..n Termine(terminId global eindeutig,kid); Person darf0..n Termine besuchen, Termin0..n Personen, höchstens ein Teilnahme-Satz(pid,terminId). Ein Kurs hat genau eine leitende Person, eine Person0..n Leitungen. Leitung und Besuch sind unabhängige Rollen. Teilnahme ist nur bei aktiver Buchung derselben Person für den zum Termin gehörigen Kurs zulässig. Termine={(T10,10),(T20,20),(T30,30),(T40,40),(T50,50)}; Leitung={(10,1),(20,4),(30,1),(40,3),(50,5)}. Diese Regel erzwingt keine Buchung für bloßes Leiten.'''
M['BCNF']='''M10 – Zusätzliches atomwertiges Schema Z(student,fach,dozent) mit FDs (student,fach)->dozent und dozent->fach, sonst nur deren Folgerungen. Daten={(Ada,DB,Dia),(Ben,DB,Dia),(Ada,Web,Wes)}. Eine Person kann mehrere Fächer, ein Fach mehrere Dozenten haben. Kandidatenschlüssel und Normalformen sind anhand der FDs, nicht anhand zufälliger Datenbesonderheiten zu bestimmen.'''
M['COST']='''M11 – Vorgegebenes Kostenmodell (keine gemessene DBMS-Laufzeit):10000 Kurs-Zeilen,1000000 Buchung-Zeilen; genau100 Kurse erfüllen preis<=20 und zu diesen gehören insgesamt10000 Buchungen. Ein nicht selektiertes kartesisches Produkt hätte10^10 Paare. Selektierte Kurse X Buchung haben10^8 Paare. Ein Hash-Join kostet n+m gelesene Eingabezeilen; frühe Kursselektion plus Hash-Join verarbeitet100+1000000=1000100 Zeilen, wobei der Kursvollscan10000 zusätzlich kostet. Ein gegebener B-Baum benötigt pro Gleichheitszugriff14 Seiten plus Ergebniszeilen; bei100 Gleichheitszugriffen auf Buchung.kid und10000 Treffern werden11400 Einheiten plus10000 Kursvollscan gezählt. Für ein separates Punktlookup gilt: Vollscan10000; B-Baum14+1; Hash durchschnittlich1+1; Hash unterstützt nach Vorgabe keine Bereichssuche. Pro Index zusätzlich2Einheiten pro Schreiben,1000Schreibungen kosten pro Index2000. Speicher: B-Baum200KiB, Hash180KiB. Beträge sind vergleichbare Modellkosten, keine Bytes oder Sekunden.'''
M['STATE']='''M12 – Ablauf innerhalb der jeweiligen Domäne: Vorgang ist zunächst Entwurf. absenden führt in den zusammengesetzten Zustand Bearbeitung. Dessen zwei orthogonale Regionen beginnen gleichzeitig: Zahlung startet Offen, zahlungOK->Bezahlt; Bereitstellung startet Wartet, bereit->Bereit. Solange Bearbeitung aktiv ist, führt abbrechen aus jedem Unterzustand nach Storniert und beendet beide Regionen. Eine Abschluss-Transition nach Erledigt ist erst erlaubt, wenn Zahlung=Bezahlt UND Bereitstellung=Bereit. Ereignisse betreffen nur ihre jeweilige Region, soweit nicht anders genannt. Aufgaben verlangen Hierarchie und echte Parallelität. Beim Festival ist Vorgang ein Auftrittsauftrag (Gage/Zahlung und Bühne/Bereitstellung); in der Bibliothek ist er eine Medienreservierung (Gebühr und Medium); bei LeihZeit Kursauftrag (Gebühr/Material).'''
M['TRANS']='''M13 – Transaktionsmaterial, Anfang Bestand(kid=10,frei=1). Ablauf L: T1 liest1,T2 liest1,T1 schreibt0 und commit,T2 schreibt0 und commit; beide behaupten erfolgreiche Platzreservierung. Ablauf D: T1 schreibt frei=0 ohne commit,T2 liest0,T1 rollback. Ablauf N: T1 liest frei=1,T2 schreibt0 und commit,T1 liest erneut0. Vorgegebene SQL-Standardgarantien: ReadUncommitted kann dirty reads erlauben; ReadCommitted verhindert dirty reads, nicht nonrepeatable reads; RepeatableRead verhindert dirty/nonrepeatable reads, Phantome je Implementierung möglich; Serializable entspricht einer seriellen Ausführung (Konflikt kann Abbruch auslösen). Für sichere Platzvergabe steht atomisches UPDATE Bestand SET frei=frei-1 WHERE kid=? AND frei>0 mit rowcount und commit im selben Transaktionsvertrag zur Verfügung.'''
M['DOMAIN']='''M14 – Domänengrenzen: Katalogservice besitzt stabile Angebotsdaten(kid,titel,preis), Ausleih-/Buchungsservice besitzt Vorgänge(id,kid,pid,status) und ihre einzelnen Positionen(id,posNr,menge). Innerhalb eines Vorgangs müssen Gesamtmenge und Positionen gemeinsam konsistent sein. Marketing besitzt Klickprofile(profilId,interessen); profilId ist keine Vorgangsidentität. Marketing darf Angebotstitel lesen, keine Vorgangstabellen schreiben. Ein Titelwechsel wird als AngebotTitelGeaendert(kid,titel,version) veröffentlicht; Verbraucher können verzögert sein. Keine verteilte atomare Transaktion über alle Dienste ist verlangt.'''
M['SEQ']='''M15 – Servicefall: Client beauftragt Reservierung bei ReservierungsService. Dieser fordert parallel Preis vom KatalogService und Verfügbarkeit vom BestandsService an. Erst nach BEIDEN Antworten darf ReservierungsService bedingt einen Platz atomar reservieren; bei Preisfehler oder ausverkauft keine Erfolgsantwort. Danach wird BenachrichtigungsService asynchron informiert. Preislesen reserviert keinen Platz. Modellieren Sie Nachrichten, Lebenslinien, Parallelfragment und Zusammenführung, einschließlich Fehlerpfad; Texte/ASCII sind bei eindeutiger Ereignisordnung erlaubt.'''
M['THREAT']='''M16 – Vorgegebene OWASP-Ausschnittskarte,nach der offiziellen Projektseite OWASP Top10:2025 am07.11.2026 geprüft:https://top10.owasp.org/2025/ . Auswahl A01 BrokenAccessControl,A02 SecurityMisconfiguration,A04 CryptographicFailures,A05 Injection,A07 AuthenticationFailures;didaktische Paraphrasen,keine Vollprüfung aller zehn Felder: BrokenAccessControl=fehlende Objekt-/Rollenprüfung; Injection=Steuerbefehle aus ungeprüften Eingaben; AuthenticationFailures=unsichere Anmeldung/Sitzung; SecurityMisconfiguration=unnötig offene Debug-/Datenendpunkte; CryptographicFailures=Schutz vertraulicher Daten bei Transport/Speicherung unzureichend. Fälle: fremde pid in URL liefert fremde Kontaktadresse; SQL wird aus titel verkettet; Cookie bleibt nach Logout gültig; /debug veröffentlicht Konfiguration; Passwortliste reist unverschlüsselt. Angreifer ist externer Nutzer, schützenswert sind Kontaktdaten und Buchungsintegrität; Browser->Server und Server->DB sind Vertrauensgrenzen.'''
M['RANK']='''M17 – Datenökonomie: Rankinguniversum sind ALLE fünf M2-Kurse, auch ohne Klick. Klickzahlen kid10=3,20=2,30=1,40=0,50=0; fehlende Klickzählung wird0, fehlender Sponsorbetrag0; KursID ist nie NULL. RankingN: Klickzahl absteigend,dann kid aufsteigend. RankingW: Sponsor zuerst (kid50 ist einziger Sponsor),danach Klickzahl absteigend,kid aufsteigend. Sponsor zahlt10EUR, direkte Werbekosten6EUR; weitere Fix-/Gemeinkosten unbekannt. Anbieter kann durch Sichtbarkeit bezahlter Angebote Erlös steigern; Datenfilterung verändert, welche Angebote zuerst wahrgenommen werden. Eine von diesen Daten bewiesene kausale Meinungsänderung wird nicht behauptet.'''
M['LARGE']='''M18 – Arbeitslasten: Vertragsbuchungen brauchen konsistente Schlüssel/FKs, atomare Platzvergabe und wechselnde relationale Auswertungen. Separat fallen laut Szenario100Millionen flexible Klickereignisse/Tag an; typische Analyse liest Kurse pro Tag über verteilte Partitionen, ohne transaktionelle Verknüpfung zur Buchung. Vorgegebene Modellkarte: relational=Tabellen/Joins/Constraints; Dokument=ein Dokument mit variablen Feldern, etwa {event,kid,extras}; WideColumn=nach Abfrageschlüssel partitionierte, spärliche Zeilen, z.B.(tag,kid)->Zeitstempelereignisse. Kein Ansatz ist von sich aus schneller/sicherer. Kleine MapReduce-Fixture: PartitionP1=(e1,10),(e2,20),(e3,10),P2=(e4,30),(e5,20),(e6,10), jedes Ereignis genau einmal.'''
M['SETTINGS']='''M19 – Fiktive lokale Konfiguration {personalizedRecommendations:true,preciseLocation:true,profilePublic:true,analyticsRetentionDays:365,language:'de',bookingNotifications:true}. Erlaubte Analysefristen7/30/365Tage. Nutzer will weniger Profilbildung/Standortoffenlegung, privates Profil und kurze optionale Analyse, aber Buchungsbenachrichtigungen und Sprache behalten. Ändern Sie nur eine Kopie; es wird kein reales Konto verwendet. Notwendige Vertragsbelege werden nicht automatisch gelöscht.'''
add('2cf','Modellieren Sie M1 einschließlich Identitäten, Beziehungen, jeweils min/max und optionaler Rückgabe. Begründen Sie, weshalb die Wiederholung von Ausleihen einen eigenen Vorgang braucht und die Offen-Regel keine bloße Kardinalität ist.',
'''Mitglied(MitgliedNr), Gerät(SerienNr), Standort(StandortNr), Ausleihe(AusleihNr) sind Entitäten mit den genannten Schlüsseln. Mitglied0..n–Ausleihe1..1, Gerät0..n–Ausleihe1..1, Standort0..n–Gerät1..1. Ausleihe trägt Startdatum und optional Rückgabedatum. Wiederholte Ausleihen sind eigene Vorgänge, nicht PK(MitgliedNr,SerienNr) oder Name. Die maximale Zahl gleichzeitig offener Ausleihen je Gerät ist eine zeitliche Zusatzbedingung. Zulässig: GerätG1 wird zuerst vonM1, später erneut vonM1 geliehen; unzulässig: zwei offene Ausleihen fürG1. Gerät ohne Ausleihe und leerer Standort bleiben zulässig.''',
['Identifizierte Entitäten und wiederholbare Ausleihe mit eigener Identität fachlich korrekt modelliert.','Alle drei Beziehungen und Optionalität mit begründeten min/max korrekt; offene-Ausleihe-Zusatzregel erkannt.'],['MODEL'])
add('42a','Leiten Sie aus M1 Relationen mit PK/FK/NULL ab. Begründen Sie die Relation für wiederholte Ausleihen und die Richtung der obligatorischen Standortreferenz. Eine reine Kopie von M2 erfüllt dies nicht.',
'''Mitglied(MitgliedNr PK,Name NOT NULL); Standort(StandortNr PK,Name NOT NULL); Gerät(SerienNr PK,Bezeichnung NOT NULL,StandortNr NOT NULL FK->Standort); Ausleihe(AusleihNr PK,MitgliedNr NOT NULL FK->Mitglied,SerienNr NOT NULL FK->Gerät,Startdatum NOT NULL,Rückgabedatum NULL). Wiederholung verlangt separate AusleihNr. FK in Gerät verwirklicht genau einen Standort, nicht umgekehrt. Offen-Regel gesondert z.B. partieller UNIQUE-Index auf Ausleihe.SerienNr WHERE Rückgabedatum IS NULL; dieser Zusatz ist keine zwingend zu beherrschende SQL-Syntax. Keine Tabellen für Team/Kurs aus M2 sind eine Lösung für M1.''',
['M1 konsistent in vier Relationen mit den richtigen Primärschlüsseln überführt.','Fremdschlüsselrichtungen/Obligatorik und optionale Rückgabe begründet; Wiederholungen bleiben möglich.'],['MODEL'])
add('46b','Zeigen Sie an M4 je eine konkrete Änderungs-, Einfüge- und Löschanomalie. Überführen Sie den Listenexport über1NF und2NF in3NF. Nennen Sie Schlüssel/FDs und begründen Sie verlustfreie Verknüpfung. BCNF ist hier nicht gefordert.',
'''Ändern nur einer Fotobasis-Preisangabe erzeugt Widerspruch. Ein neuer Kurs ohne Buchung lässt sich nicht als regulärer E-Satz speichern. Löschen von Bens einziger Audiolaborbuchung entfernt dessen Kursdaten.1NF: Listen entpacken zu vier Tupeln E mit PK(pid,kid).2NF: Person(pid PK,pseudonym,ort), Buchung(pid,kid,status,PK(pid,kid)), KursZ(kid PK,titel,preis,tid,teamName); partielle FDs sind entfernt.3NF: Kurs(kid PK,titel,preis,tid FK),Team(tid PK,teamName) statt KursZ, weil kid->tid->teamName. Buchung hat FKs zu Person/Kurs. Die FDs pid->...,kid->...,tid->... und diese Schlüssel sichern verlustfreie Rekonstruktion vorhandener E-Tupel; keine zusätzlichen Kombinationen bei den Joins. Ein Modell ohne Listen kann bereits1NF sein, löst aber den gegebenen Listenexport erst nach Entpacken.''',
['Drei konkrete Anomalien und Listenauflösung zur1NF mit Schlüssel/FDs korrekt.','Partielle und transitive Abhängigkeiten bis3NF korrekt getrennt, PK/FK und Verlustfreiheit begründet.'],['NORM'])
add('fd1','Verfassen Sie selbst SQL für pseudonym,titel,preis aktiver Buchungen von Kasseler Personen zu Kursen ab20EUR. Sortieren Sie preis absteigend,pseudonym aufsteigend,kid aufsteigend,pid aufsteigend. Geben Sie alle Tupel an. Verknüpfen Sie anhand der dokumentierten FKs, nicht pid=kid.',
'''SELECT p.pseudonym,k.titel,k.preis FROM Person p JOIN Buchung b ON b.pid=p.pid JOIN Kurs k ON k.kid=b.kid WHERE p.ort='Kassel' AND b.status='aktiv' AND k.preis>=20 ORDER BY k.preis DESC,p.pseudonym,k.kid,p.pid;
Vollständiges Ergebnis(pseudonym,titel,preis): [('ada','Videoschnitt',40),('ben','Audiolabor',30),('ada','Fotobasis',20),('ben','Fotobasis',20)]. pid=kid erzeugt hier keine Zeile, fehlende Joins erzeugen falsche Kombinationen. INNER JOIN oder äquivalentes WHERE-Join ist zulässig.''',
['Selbst formulierte Abfrage projiziert die verlangten Spalten mit beiden korrekten Joins und allen Filtern.','Ordnung und vollständige vier Ergebnistupel richtig; korrekte SQL-Lösung mit einzelnem Abschreibfehler im ausgegebenen Preis behält SQL-Kriterium.'],['DB'])
add('13b','Berechnen Sie per eigener SQL-Abfrage pro Kurs mit mindestens einer aktiven Buchung kid,Anzahl aktiver Buchungen und geplanten Umsatz(preis je aktiver Buchung). Verwenden Sie Gruppierung und Aggregatfunktionen, geben Sie das vollständige Ergebnis nach kid an. Kurse ohne aktive Buchung gehören hier nicht zum Ergebnis; LEFT JOIN/HAVING werden nicht vorausgesetzt.',
'''SELECT k.kid,COUNT(*) AS anzahl,SUM(k.preis) AS umsatz FROM Kurs k JOIN Buchung b ON b.kid=k.kid WHERE b.status='aktiv' GROUP BY k.kid ORDER BY k.kid;
Ergebnis(kid,anzahl,umsatz)=[(10,2,40),(20,2,60),(30,2,80),(40,1,10)]. Kurs50 fehlt absichtlich. COUNT(b.pid) ist hier äquivalent, weil innerer Join und pid NOT NULL. Alle Buchungen ohne Statusfilter ergäben für10 fälschlich3 und für40 fälschlich2.''',
['Eigene Gruppierung mit aktivem Join/Filter und korrekter COUNT-/SUM-Bedeutung.','Mehrfachzeilen pro Gruppe richtig verarbeitet und alle vier Aggregattupel ermittelt.'],['DB'])
add('e00','Schreiben Sie ein beschriftetes Formular für GET /kurse mit maxPreis=30 und zeigen Sie die tatsächlich entstehende Request-URL. Schreiben Sie ein kleines POST-Formular für /titel mit kid10 und neuem Titel Grundlagenkurs. Erläutern Sie GET/POST anhand der gelieferten Verträge; Authentifizierung/CSRF sind hier gegeben.',
'''<form action="/kurse" method="get"><label for="p">Höchstpreis EUR</label><input id="p" name="maxPreis" type="number" min="0" max="1000" value="30" required><button>Suchen</button></form>
Request: GET /kurse?maxPreis=30 .
<form action="/titel" method="post"><input name="kid" type="hidden" value="10"><label for="t">Titel</label><input id="t" name="titel" value="Grundlagenkurs" maxlength="80" required><button>Ändern</button></form>
POST /titel mit Body kid=10&titel=Grundlagenkurs, Content-Type application/x-www-form-urlencoded. GET liest und ist verlinkbar, POST sendet hier einen Änderungsauftrag. Clientgrenzen sind Komfort; gelieferter Server prüft erneut. Für diese Grundaufgabe wird keine eigene Sicherheits-/Sessionbibliothek verlangt.''',
['Formulare liefern die passenden Namen,Werte,Methoden und Ziele; mindestens Suchfeld benutzbar beschriftet.','Konkrete GET-URL und POST-Body passen zum Vertrag,Methodenunterschied anhand des Falls erklärt.'],['WEB'])
add('0cf','Implementieren Sie mit M6 eine Datenbankverbindung, parametriertes SELECT und Ausgabe/Iteration aller Kurse bis zum gegebenen max_preis30, nach kid. Verbindung auch bei Fehler schließen. Das SQL ist eigenständig zu formulieren, die API ist geliefert. Ergebnis nennen.',
'''import sqlite3
from contextlib import closing
with closing(sqlite3.connect(db_path)) as con:
    rows=con.execute('SELECT kid,titel,preis FROM Kurs WHERE preis<=? ORDER BY kid',(max_preis,)).fetchall()
for kid,titel,preis in rows:
    print(kid,titel,preis)
Bei30: [(10,'Fotobasis',20),(20,'Audiolabor',30),(40,'Datenschutz-Werkstatt',10),(50,'Archiv <offen>',15)]. Verbindung entsteht vor execute, Parameter werden getrennt gebunden, alle Zeilen gelesen und iteriert. Bei Fehler schließt closing; der Server darf danach kontrolliert500 liefern. HTML-Ausgabe ist eine eigene Aufgabe.''',
['Verbindungsaufbau,vorbereitetes/parametrisiertes SELECT und gesicherte Freigabe korrekt implementiert.','Ergebnis wird tatsächlich abgerufen und vollständig iteriert/ausgegeben; vier erwartete Zeilen.'],['DB','WEB'])
add('71f','Wenden Sie M7 auf notwendige Buchungsdaten und die getrennte Werbung an. Erläutern Sie informationelle Selbstbestimmung, Personenbezug, zwei Prinzipien, die konkrete Rechtsgrundlage je Zweck sowie Information und Widerruf/Widerspruch. Keine Ergänzung erfundener Normen erforderlich.',
'''Die zuordenbaren Pseudonyme bleiben personenbezogen. Selbstbestimmung schützt die grundsätzlich eigene Entscheidung über Datenpreisgabe und Verwendung innerhalb des rechtlichen Rahmens. Zweckbindung verbietet hier die stillschweigende Umnutzung der Buchungsdaten für AdCo; Minimierung spricht gegen unnötige Standort-/Kontaktweitergabe; Speicherbegrenzung gegen endlose Klickprofile. Notwendige Vertragsdaten: Art.6Abs.1b. Die hier ausdrücklich freiwillige separate Werbung: Art.6Abs.1a mit freiwilliger,informierter,bestimmter,nachweisbarer Einwilligung; keine Kopplung an die Buchung und jederzeit leicht widerrufbar nachArt.7. Art.13 verlangt hier Zwecke,Grundlagen,Empfänger,Fristen und Rechte zu erläutern. Einwilligungswiderruf beendet künftige darauf gestützte Werbung; Direktwerbewiderspruch nachArt.21Abs.2/3 stoppt diese Verarbeitung. Er beseitigt nicht automatisch unabhängig erforderliche Vertragsbelege. Andere tatsächliche Werbekanäle/Rechtsgrundlagen wären gesondert zu prüfen, werden hier nicht behauptet.''',
['Personenbezug,Selbstbestimmung und mindestens zwei Datenschutzprinzipien korrekt am Fall erläutert.','Vertrag und freiwillige Werbung mit Art.6b/6a getrennt,Einwilligungsbedingungen,Information und betroffene Rechte/Folgen korrekt.'],['LAW'])
add('58173','Erstellen Sie zu den vier Vorfällen in M8 einen Maßnahmenplan mit Schutzziel,Maßnahme,Verantwortung und prüfbarer Kontrolle. Begründen Sie mindestens zwei organisatorische Maßnahmen, eine technische/physische Maßnahme und ein Restrisiko. Beziehen Sie Authentizität ein, ohne einen vollständigen BY12-Kurs zu behaupten.',
'''Vertraulichkeit: individuelle rollenbegrenzte Konten statt Sammeladmin; Leitung genehmigt Rollen,Administration setzt um,quartalsweise Rechteprüfung durch Datenverantwortliche. Integrität: protokollierter Freigabeprozess für Kapazitätsänderungen,DB-Constraints und Vier-Augen-Freigabe; monatliche Stichprobe. Verfügbarkeit: räumlich getrennte verschlüsselte Backups und monatlicher protokollierter Restoretest auf Ersatzgerät durch Administration; Leitung prüft das Protokoll. Authentizität: Änderungsaufträge nur über authentifizierten Kanal oder Rückruf bei bekanntem Kontakt; Datenverantwortliche prüft Identität statt nur Absendername. Restrisiken: Daten seit letztem Backup können fehlen,Einzelkonto kann kompromittiert werden. Reine Verschlüsselung macht ein ungetestetes Backup nicht wiederherstellbar.''',
['CIA und Authentizität am jeweiligen Vorfall richtig zugeordnet und passende Maßnahmen begründet.','Zuständigkeit,prüfbare organisatorische Kontrollen und verhältnismäßiges technisches/physisches Mittel samt Restrisiko konkret.'],['SEC'])
add('fdfa','Berechnen Sie für M3 vollständig mit Resultatschemata:(a) R×S,(b) sigma_a=1(R),(c) pi_x(R),(d) R JOIN_x=y S. Geben Sie alle Tupel, keine bloßen IDs an, und erklären Sie den Unterschied Produkt/Join.',
'''R×S(a,x,b,y)={(1,'rot',10,'rot'),(1,'rot',20,'gruen'),(2,'blau',10,'rot'),(2,'blau',20,'gruen')}. sigma_a=1(R)(a,x)={(1,'rot')}. pi_x(R)(x)={('rot'),('blau')}. R JOIN_x=y S(a,x,b,y)={(1,'rot',10,'rot')}. Join ist Selektion x=y aus dem Produkt, nicht bloß Namensgleichheit. Mengenprojektion entfernt doppelte Tupel; Reihenfolge ist unerheblich.''',
['Produkt und Selektion mit korrekten Schemata und vollständigen Tupeln ausgeführt.','Projektion und Theta-Join mit Mengenbedeutung und vollständigen Tupeln ausgeführt.'],['ALG'])
add('b592','Neue Frage zu M3: Welche unterschiedlichen Farben x besitzen R-Tupel, die über V mit b=20 verbunden sind? Entwickeln Sie selbst RA-Term und äquivalentes SQL, erklären Sie die Operatorentsprechung und bestimmen Sie das Ergebnis. Dies ist eine andere Frage als der vorgegebene Term der Übersetzungsaufgabe.',
'''pi_x(R JOIN_R.a=V.a sigma_b=20(V)). SELECT DISTINCT r.x FROM R r JOIN V v ON v.a=r.a WHERE v.b=20 ORDER BY r.x;
Ergebnis(x)={('rot'),('blau')}; sortiertes SQL:[('blau'),('rot')]. sigma filtert V,Join bindet passende a,pi/SELECT DISTINCT liefert Farben als Menge. Kein Join mit S nötig. Gleichwertiger Unterabfrage-/EXISTS-Weg wird akzeptiert, wenn zusätzlich ein korrekter selbst entwickelter RA-Term vorliegt.''',
['Problem selbst in einen korrekten RA-Term mit Filter,Join und mengenwertiger Projektion übersetzt.','Äquivalentes SQL und vollständige Ergebnismenge samt Operatorentsprechung korrekt.'],['ALG'])
add('9a49','Prüfen Sie dieses separate fehlerhafte Schema: KursB(kid PK,titel,tid,teamName),BuchungB(id PK,pid,kid,status),ohne FKs/UNIQUE/CHECK. Daten KursB={(10,Fotobasis,1,Werkstatt),(30,Videoschnitt,1,Werkstad)};BuchungB={(701,1,10,aktiv),(702,1,10,storniert)}. Es gelten M2-Geschäftsregeln und tid->teamName. Beurteilen Sie Schlüssel,Redundanz,Konsistenz und eine lokal ausreichende Reparatur,ohne erneut eine ganze Normalisierung zu verlangen.',
'''id ist technisch eindeutig,erzwingt aber kein eindeutiges(pid,kid);die beiden Sätze widersprechen dem einzigen aktuellen Buchungsstatus. UNIQUE(pid,kid) oder PK(pid,kid), NOT NULL,FKs und Status-CHECK reparieren Constraints. tid1 hat zwei widersprüchliche Namen; separates Team(tid PK,name),Kurs.tid als FK entfernt redundante Namen. Vor Migration muss fachlich geklärt werden,welcher Status/Name stimmt; beliebiges Löschen ist keine belegte Korrektur. Neue Constraints allein heilen alte Widersprüche nicht.''',
['Schlüsselgrenze und beide konkreten Redundanz-/Konsistenzfehler korrekt bewertet.','Lokal ausreichende Schlüssel/Referenz/Werte- und Teamreparatur samt nötiger Bestandsklärung begründet.'])
add('042','Geben Sie SQL-Ergebnisse als strukturierte,escaped HTML-Tabelle aus. Wählen Sie genau EINEN Weg:(F) implementieren Sie GET /kurse mit Preisfilter,ohne Pagination; (P) implementieren Sie GET /seiten mit stabiler Pagination(Größe2),ohne Filter. Nutzen Sie M6-Helfer. F: zeigen Sie maxPreis30 und leeres maxPreis0; P: zeigen Sie Seiten1,3,4 und ungültige0/5000-Ziffern. Beide Wege müssen den Titel Archiv <offen> als Text zeigen können. Nur ein Weg ist erforderlich.',
'''Gemeinsamer Renderer: '<table><thead><tr><th>ID</th><th>Titel</th><th>Preis EUR</th></tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+html.escape(str(v),quote=True)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'; bei leerer Liste zusätzlich Text 'Keine Treffer'. F: validierter maxPreis,SELECT kid,titel,preis FROM Kurs WHERE preis<=? ORDER BY kid,(maxPreis,);Formular/GET wie Formularaufgabe.30 liefert10,20,40,50;0 liefert[];keine Seitenlinks erforderlich. P: validierte page,SELECT kid,titel,preis FROM Kurs ORDER BY kid LIMIT ? OFFSET ?,(2,(page-1)*2);Gesamtzahl5. Seite1=[(10,Fotobasis,20),(20,Audiolabor,30)],Seite3=[(50,Archiv <offen>,15)],Seite4=[];Vor-link nur page>1,Weiter nur page*2<5,Links /seiten?page=N. Seite0 und überlange Zahl liefern400 vor int(). In beiden Wegen wird Archiv &lt;offen&gt; ausgegeben. Eigenständige vollständige ausführbare Referenzen stehen zusätzlich im Lösungsteil; sie sind keine Schülerstarter. Korrektes F besteht ohne P und umgekehrt.''',
['Ausgegebenes SQL-Resultat wird vollständig als strukturierte HTML-Tabelle mit geeigneter Text-/Attributkodierung erzeugt.','Entweder F mit wirksamem Filter und leerem Ergebnis ODER P mit stabilen Grenzen,Links und Validierung korrekt; kein Zusatzpunktzwang für den anderen Weg.'],['DB','WEB'])
add('de3','Beurteilen Sie drei Alltagsrisiken aus M19 und ändern Sie die fiktive Konfiguration tatsächlich in einer lokalen Kopie/als vollständigen Nachherzustand. Begründen Sie die Abwägung einschließlich Komfortverlust und Erhaltung der unabhängigen Felder.',
'''Nachher={personalizedRecommendations:false,preciseLocation:false,profilePublic:false,analyticsRetentionDays:7,language:'de',bookingNotifications:true}. Umsetzung: next=dict(current);next.update(personalizedRecommendations=False,preciseLocation=False,profilePublic=False,analyticsRetentionDays=7). Weniger Profilbildung mindert Personalisierung,kein genauer Ort erschwert lokale Vorschläge,privates Profil mindert Auffindbarkeit,kurze Frist mindert Rückblick. Sprache/Buchungsmitteilungen unverändert;aktuelle Originalkopie bleibt unverändert;notwendige Buchungsdaten werden nicht pauschal gelöscht. Andere begründete datensparsame erlaubte Wahl(z.B.30Tage) ist zulässig,wenn die Nutzerziele erfüllt werden.''',
['Mindestens drei konkrete Datenrisiken/Komfortabwägungen fachlich begründet.','Gültigen Nachherzustand tatsächlich erzeugt/protokolliert,unabhängige Felder erhalten und notwendige Vertragsdaten getrennt.'],['SETTINGS'])
add('e67','Übersetzen Sie diesen GEGEBENEN geschachtelten Term schrittweise auf M3: A=sigma_x=rot(R);B=V JOIN_V.b=S.b S;C=A JOIN_A.a=B.a B;D=pi_y(C). Geben Sie alle Zwischenrelationen mit vollständigen Tupeln/Schemata und äquivalentes SQL an. Nutzen Sie M3 unabhängig von früheren Lösungen.',
'''A(a,x)={(1,'rot')}. B(a,b,y)={(1,10,'rot'),(1,20,'gruen'),(2,20,'gruen')} (gleiche Joinattribute b werden einmal geführt). C(a,x,b,y)={(1,'rot',10,'rot'),(1,'rot',20,'gruen')}. D(y)={('rot'),('gruen')}.
SELECT DISTINCT s.y FROM R r JOIN (V v JOIN S s ON s.b=v.b) ON r.a=v.a WHERE r.x='rot';
Äquivalente flache Joins sind erlaubt,wenn die schrittweise Zuordnung der inneren/äußeren Verknüpfung gezeigt wird. Ausgeschriebene doppelte Joinspalten sind bei eindeutiger Benennung ebenfalls richtig. SQL sortiert bei ORDER BY s.y [('gruen'),('rot')].''',
['Gegebenen verschachtelten Term schrittweise mit vollständigen Zwischenrelationen semantisch korrekt ausgewertet.','Äquivalentes SQL mit beiden Joins,Selektion,DISTINCT und erklärter innerer/äußerer Entsprechung formuliert.'],['ALG'])
add('7a9','Ermitteln Sie aus M17 beide vollständigen Kursreihenfolgen,Werbeerlös und bekannten direkten Überschuss. Bewerten Sie ökonomischen Anreiz,Datenrisiko und eine konkrete Wahrnehmungs-/Auswahlwirkung der Filterung;grenzen Sie plausible Wirkung von empirisch bewiesener Meinungsänderung ab. NoSQL/MapReduce sind nicht nötig.',
'''N=[10,20,30,40,50],weil Klickzahl3,2,1,0,0 und Gleichstand kidaufsteigend. W=[50,10,20,30,40],weil50 als einziger Sponsor zuerst steht. Fehlende Klicks/Sponsorwerte sind0,keine Kurse verschwinden. Erlös10EUR,bekannter direkter Überschuss10-6=4EUR;kein vollständiger Gewinn ohne andere Kosten. Anreiz: Sponsor erhält Sichtbarkeit und Anbieter Geld;Profilklicks können personalisierte Verwertung ermöglichen,bergen Reidentifikations-/Zweckänderungsrisiko. Das wenig geklickte Archivangebot erscheint zuerst und kann dadurch stärker wahrgenommen/gewählt werden;die unsichtbare Rangordnung ist kein neutraler Vollständigkeitsbeweis. Diese Zahlen beweisen keine kausale Meinungänderung,alternative transparente Sortierung/Kennzeichnung mindert Täuschung.''',
['Beide vollständigen Rankings mit Null-/Tie-Regel und ökonomische Rechnung samt Kostengrenze richtig.','Ökonomische Verwertbarkeit und konkreter Filter-/Wahrnehmungseffekt samt Datenrisiko begründet,evidenzielle Grenze erkannt.'],['DB','RANK'])
# Four newly explicit performances retain new independent result identities.
add('5c6','Kurs besitzt Termine. TerminNr ist nur innerhalb ihres Kurses eindeutig,jeder Termin gehört genau einem Kurs;Kurs10 und20 dürfen jeweils TerminNr1 besitzen,Kurs darf0..n Termine haben. Modellieren Sie schwachen Entitätstyp,partiellen Schlüssel und identifizierende Beziehung;leiten Sie das Relationenschema ab.',
'''Kurs(KursID PK,titel);Termin(KursID NOT NULL FK->Kurs,TerminNr NOT NULL,Datum NOT NULL,PK(KursID,TerminNr)). Termin ist existenz-/identifikationsabhängig: partielle TerminNr genügt nur zusammen mit Besitzer-KursID. Kurs0..n–Termin1..1 identifizierend,totale Teilnahme des Termins. (10,1,2027-02-01) und(20,1,2027-02-02) sind verschieden;zwei(10,1,...) unzulässig. Globale UNIQUE(TerminNr) wäre eine unbegründete Verschärfung.''',
['Schwäche,partieller Schlüssel,totale Teilnahme und identifizierende1:n-Beziehung korrekt modelliert.','Zusammengesetzten PK(KursID,TerminNr) und Besitzer-FK korrekt abgeleitet;gleiche Nummer in anderen Kursen bleibt erlaubt.'])
add('2d1','Eine Person hat0..n Telefonnummern,dieselbe Nummer darf mehreren Personen gehören,keine doppelten(Person,Nummer)-Paare. Erkennen/modellieren Sie Mehrwertigkeit und überführen Sie sie mit Schlüsseln ins relationale Modell. Zeigen Sie Beispiele für keine Nummer,zwei Nummern und geteilte Nummer.',
'''Person(PersonID PK,Name);Telefon(PersonID NOT NULL FK->Person,Nummer NOT NULL,PK(PersonID,Nummer)). Mehrwertiges Attribut Nummer der Person wird zur eigenen Relation;keine kommaseparierte Liste,keine globale Eindeutigkeit der Nummer. Person1 ohne Nummer hat keine Telefonzeile;Person2 hat(2,'0123'),(2,'0456');Person3 darf(3,'0123') haben;zweites(2,'0123') unzulässig. Nummer als Text erhält führende Nullen.''',
['Mehrwertigkeit0..n erkannt und ohne Listen-/Ein-Nummer-Beschränkung relational dargestellt.','Besitzer-FK und eindeutiges zusammengesetztes Paar korrekt;Nullmenge und geteilte Nummer bleiben möglich.'])
add('58180','Lehrkraft ist Spezialisierung von Person,jede Lehrkraft ist Person,nicht jede Person ist Lehrkraft. Gegebenes zulässiges Abbildungsmuster: separate Untertyptabelle. Modellieren Sie is-a und Schlüsselbeziehung,mit Lehrgebiet nur bei Lehrkraft;weitere Strategien sind nicht verlangt.',
'''Person(PersonID PK,Name);Lehrkraft(PersonID PK und FK->Person,Lehrgebiet NOT NULL). is-a zeigt Lehrkraft als Teilmenge von Person;Identität wird geerbt. Person7 kann ohne Lehrkraftzeile bestehen,Lehrkraft8 ohne Person8 nicht. Lehrkraft braucht keinen unabhängigen LehrkraftID-Schlüssel;keine Annahme,dass jede Person Lehrkraft wird. Keine zusätzliche Disjunktheits-/Vollständigkeits-/OO-Implementierungsanforderung.''',
['is-a-Richtung und Teilmengenbedeutung einschließlich nicht notwendiger vollständiger Spezialisierung korrekt.','Separate Untertyptabelle mit identischem PK/FK und untertypspezifischem Lehrgebiet konsistent dargestellt.'])
add('b855','Vorgegeben: UPDATE Kurs SET titel=? WHERE kid=? . Führen Sie dies aus einem eigenen Programm für Titel Grundlagenkurs und Kurs10 aus,M6-API. Es gibt keine Ergebnismenge. Prüfen Sie über neue Verbindung nach commit(),dass nur Kurs10 geändert ist. Dokumentieren Sie betroffene Zeilen und Fehler-/Close-Verhalten;kein DDL/DCL/Isolation gefordert.',
'''con=sqlite3.connect(db_path)
try:
    cur=con.execute('UPDATE Kurs SET titel=? WHERE kid=?',('Grundlagenkurs',10))
    affected=cur.rowcount
    con.commit()
except sqlite3.Error:
    con.rollback()
    raise
finally:
    con.close()
with closing(sqlite3.connect(db_path)) as check:
    after=check.execute('SELECT kid,titel FROM Kurs ORDER BY kid').fetchall()
assert affected==1
# after=[(10,'Grundlagenkurs'),(20,'Audiolabor'),(30,'Videoschnitt'),(40,'Datenschutz-Werkstatt'),(50,'Archiv <offen>')]
execute bindet Titel und ID getrennt;kein fetchall() auf UPDATE. SELECT-only oder fehlendes commit mit nur derselben Verbindung beweist den Vertragszustand nicht. Fehler rollback/close nach API.''',
['Vorgegebenes UPDATE mit gebundenen Werten tatsächlich ohne Ergebnismengenabruf und mit commit ausgeführt.','Betroffene Zeile und persistenter Nachzustand über neue Verbindung geprüft,andere vier Titel unverändert;Fehler/Freigabe dem Vertrag entsprechend.'],['DB','WEB'])
add('2e2','Beschreiben Sie fachlich und mit konkretem M2-Ergebnis: SELECT kid FROM Kurs WHERE preis>(SELECT AVG(preis) FROM Kurs); UPDATE Kurs SET preis=preis+5 WHERE kid=20; ALTER TABLE Kurs ADD COLUMN sichtbar INTEGER NOT NULL DEFAULT1; GRANT SELECT ON KursAuskunft TO auskunft. Ordnen Sie DML,DDL,DCL zu;erläutern Sie Unterabfrage/äußere Abfrage und Rechtegrenze. Sicht/Rollen nach M5 sind vorausgesetzt.',
'''Inneres AVG=(20+30+40+10+15)/5=23;äußerer SELECT liefert(kid)={(20),(30)}. SELECT ist lesende Abfrage(je Lehrkonvention DQL oder DML-Leseteil,beides zulässig). UPDATE ist DML,ändert nur Kurs20 von30auf35. ALTER ist DDL,ergänzt sichtbar mit NOT NULL und Default1;alle vorhandenen Zeilen erhalten1. GRANT ist DCL,erlaubt SELECT nur auf KursAuskunft,kein Schreiben und kein direkter Person-/Kontaktzugriff. Jeder Befehl startet bei M2;KursAuskunft zeigt nur kid,titel,preis.''',
['Unterabfrage und äußerer Schritt mit konkretem Mittelwert/Ergebnis korrekt beschrieben.','DML-/DDL-Wirkung und DCL-Reichweite vollständig und richtig klassifiziert.'],['DB','ROLES'])
add('431','Entwerfen und begründen Sie für M5 die Benutzer-/Rechteorganisation einer Webdatenbank: Zuordnung öffentlicher Weblesezugriff und angemeldeter Buchungsdienst,Umgang mit DB-Zugangsdaten und regelmäßiger Rechteprüfung. Zeigen Sie an drei Beispieloperationen,was erlaubt/abgewiesen wird.',
'''Server verwendet getrennte DB-Dienstkonten für auskunft und anmeldedienst;Browser erhält keine DB-Zugangsdaten. Personen werden durch gelieferte Websitzung identifiziert,DB-Rolle ist davon getrennt. auskunft: SELECT KursAuskunft erlaubt,SELECT Kontakt verboten,UPDATE Kurs verboten. anmeldedienst:INSERT Buchung erlaubt,SELECT Buchung erlaubt,DROP Kurs verboten. Rechte nach minimalem Bedarf und regelmäßiger protokollierter Entzug bei Rollenwechsel;Secrets nur serverseitig,kein Sammeladmin im Web. Rollen schützen Tabellen,nicht automatisch die fachliche Zuordnung einer Buchung zum angemeldeten Nutzer;Server prüft dies zusätzlich.''',
['Benutzer-/Dienstrollentrennung und minimale Rechte an konkreten Operationen zutreffend beschrieben.','Serverseitige Zugangsdatenverwaltung,Rechtepflege und Grenze gegenüber Objekt-/Sessionautorisierung begründet.'],['ROLES','WEB'])
add('56e','Zu M3 seien U(a)={(1),(2)} und W(a)={(2),(3)}. Berechnen Sie U vereinigt W,U geschnitten W,U minus W und rho_q(z)(U). Nennen Sie Schemata und vollständige Tupel,erklären Sie Kompatibilität und gerichtete Differenz.',
'''Union(a)={(1),(2),(3)};Schnitt(a)={(2)};U-W(a)={(1)};W-U wäre{(3)}. rho_q(z)(U) heißt Relation q mit Schema(z)={(1),(2)}. Werte bleiben unverändert. Union/Schnitt/Differenz brauchen kompatible Attributdomänen/Schema;Umbenennung ändert Bezeichner,keine Daten. Reihenfolge egal.''',
['Vereinigung,Schnitt und gerichtete Differenz vollständig mit kompatiblem Schema ausgeführt.','Umbenennung von Relation/Attribut ohne Datenänderung korrekt und begründet.'])
add('1eb','Modellieren und begründen Sie die drei Beziehungen und die Zusatzbedingung in M9. Geben Sie erlaubte und unerlaubte konkrete Teilnahme an und erklären Sie,warum binäre Kardinalitäten allein nicht genügen.',
'''Kurs1..n–Termin1..1;Person0..n–Teilnahme1..1 und Termin0..n–Teilnahme1..1;Teilnahme PK(pid,terminId). Person0..n–leitet–Kurs1..1,Leitung unabhängig vom Besuch. Für jede Teilnahme(p,t) muss es k geben mit Termin(t,k) und Buchung(p,k,'aktiv'). (1,T20) ist unzulässig,weil1 keine aktive20-Buchung hat;(2,T20) ist zulässig. Binäre min/max erzwingen keine Übereinstimmung des Terminkurses mit der aktiven Buchung. Ein Leiter ohne Teilnehmerbuchung ist zulässig.''',
['Alle komplexen min/max-/Rollenregeln einschließlich Leitungsunabhängigkeit begründet modelliert.','Kursübergreifende Teilnahmebedingung präzise und mit positivem/negativem Tupel sowie Kardinalitätsgrenze erklärt.'],['DB','COMPLEX'])
add('16c','Wenden Sie DDL,DML,DCL an: CREATE für Hinweis(kid,text) mit höchstens einem Hinweis je existierendem Kurs;INSERT10/Kamera mitbringen,UPDATE zu Geladene Kamera mitbringen,DELETE desselben Hinweises. Erzeugen Sie KursAuskunft und stellen Sie mit GRANT/REVOKE exakt M5 her. Zeigen Sie Zwischen-/Endzustände und was bei unbekanntem/doppeltem kid geschieht.',
'''CREATE TABLE Hinweis(kid INTEGER PRIMARY KEY REFERENCES Kurs(kid),text TEXT NOT NULL);
INSERT INTO Hinweis(kid,text) VALUES(10,'Kamera mitbringen');
UPDATE Hinweis SET text='Geladene Kamera mitbringen' WHERE kid=10;
DELETE FROM Hinweis WHERE kid=10;
CREATE VIEW KursAuskunft AS SELECT kid,titel,preis FROM Kurs;
GRANT SELECT ON KursAuskunft TO auskunft;
REVOKE SELECT ON Person FROM auskunft;
GRANT SELECT,INSERT ON Buchung TO anmeldedienst;
Nach Insert[(10,'Kamera mitbringen')],nach Update[(10,'Geladene Kamera mitbringen')],nach Delete[]. PK verhindert doppelten kid,FK unbekannten Kurs. Keine Kontakt-/DROP-/UPDATE-Rechte an Dienstrollen. DDL/DML in SQLite tatsächlich ausführbar;DCL ist hier Anwendung/Formulierung im expliziten SQL-Rollenmodell und wird nicht als SQLite-Ausführung ausgegeben.''',
['DDL mit PK/FK und gezielte INSERT/UPDATE/DELETE samt Zuständen fachlich korrekt angewandt.','Sicht und GRANT/REVOKE bilden exakt die vorgegebene Rechtepolitik ohne übermäßige Rechte ab.'],['DB','ROLES'])
add('705','Sichern Sie GET maxPreis und POST /buchen serverseitig nach M6 ab:genau ein Wert,beschränkte Länge/ASCII-Zahl/Bereich,vorgegebene Session und CSRF. Zeigen Sie Ergebnisse für maxPreis=0 OR1=1,page=-1,zweifache page,5000-Ziffern,maxPreis=30,falschen Token und fremdes pid-Feld. Beschreiben Sie SQL-Bindung und die Grenzen von POST.',
'''Ein Wert je erlaubtem Namen,unbekannte/fehlende Namen->400;vor int() maximal4Zeichen(maxPreis),3(page),7(kid),dann ASCII-Ziffern und Bereich prüfen. '0 OR1=1',-1,doppelte page,5000-Ziffern->400;30 ist zulässig;falscher csrfToken->403;mitgelieferte pid wird abgewiesen,Sessionpid=1 ist maßgeblich. GET darf keine Änderung auslösen. POST /buchen akzeptiert nur kid/csrfToken,prüft Kurs/Existenz und fachlichen Status,bindet SQL-Werte mit ?. HTTPS schützt Transport,POST allein nicht;CSRF ersetzt weder Anmeldung noch Objektberechtigung. Kontrolliertes400 vor Zahlenkonvertierung verhindert überlange int()-Ausnahme. Ein allgemeines Weglöschen von Zeichen ist keine sichere fachliche Validierung.''',
['GET/POST-Validierung mit Längenprüfung vor int und allen positiven/negativen Fällen korrekt umgesetzt/präzisiert.','Getrennte SQL-Bindung,gegebene Sitzung/CSRF und zusätzliche Sicherheitsgrenzen von POST korrekt beschrieben.'],['WEB','DB'])
add('121','Verfeinern Sie M14 mit mindestens zwei Bounded Contexts und einem echten Aggregat mit Wurzel. Benennen Sie Eigentümer,Invariante und Kontextübergang. Erklären Sie,warum ein beliebiger Cluster aus allen Tabellen keine passende Aggregatgrenze ist.',
'''Katalog besitzt Angebot als eigenen Kontext;Vorgangsverwaltung besitzt Vorgang mit Positionen als Aggregat,VorgangID ist Wurzel. Invariante Summe(Position.menge)=Vorgang.gesamt wird innerhalb desselben Aggregats/Transaktionsbereichs gehalten. Andere Dienste referenzieren VorgangID,können Positionen nicht unmittelbar ändern. Marketing besitzt Profil in eigenem Kontext;profilId ist keine Vorgangsidentität. Katalog veröffentlicht AngebotTitelGeaendert(kid,titel,version),Marketing übernimmt idempotent nach Version;Verzögerung akzeptiert,keine globale Transaktion. Ein Gesamtaggregat über Katalog,Vorgänge,Profile koppelte unabhängige Schreibmodelle und erzwingt hier unnötig starke Konsistenz.''',
['Bounded Contexts mit klaren Begriffen/Datenverantwortung und tatsächlichem Wurzel-/Kindaggregat begründet.','Konkrete Aggregatinvariante und kontrollierter Kontextübergang ohne gemeinsame Schreibhoheit konsistent modelliert.'],['DOMAIN'])
add('875','Modellieren Sie M12 als hierarchischen Zustandsautomaten mit zwei orthogonalen Regionen. Zeigen Sie Anfangszustände,Ereignisübergänge,Abschlussbedingung und Unterbrechung aus jedem Unterzustand. Führen Sie die Spuren absenden,bereit,zahlungOK;absenden,zahlungOK,abbrechen;absenden,bereit,abbrechen aus. Bloß lineare Kästchen oder MapReduce ersetzen diese Leistung nicht.',
'''Topzustände Entwurf,Bearbeitung,Erledigt,Storniert. Entwurf--absenden-->Bearbeitung. Bearbeitung ist zusammengesetzt mit zwei parallel aktiven Regionen: Zahlung:[initial->Offen;Offen--zahlungOK-->Bezahlt],Bereitstellung:[initial->Wartet;Wartet--bereit-->Bereit]. Nach absenden ist Konfiguration(Bearbeitung,Offen,Wartet). bereit führt(Offen,Bereit),zahlungOK dann(Bezahlt,Bereit),anschließend nur bei beiden fertig nachErledigt. Die Reihenfolge zahlungOK dannbereit führt ebenfalls Erledigt. Bearbeitung--abbrechen-->Storniert ist ein übergeordneter Ausgang,beendet beide Regionen unabhängig vom Unterzustand. Spuren2/3 endenStorniert und können nachträglich nicht durch Zahlung/Bereit-Ereignis abgeschlossen werden. Ein Schema,das nach erstem EinzelabschlussErledigt erreicht,ist falsch. Hierarchie und echte Parallelkonfiguration müssen im Modell erkennbar sein;graphische Notationsschönheit kein Kriterium.''',
['Hierarchischen Composite-Zustand und zwei gleichzeitig aktive orthogonale Regionen mit Anfangs-/Ereignisübergängen korrekt modelliert.','Synchronisierten Abschluss und übergeordneten Abbruch aus jeder Teilkonfiguration korrekt,alle Spuren fachlich richtig geprüft.'],['STATE'])
add('505','Entwerfen Sie das Sequenzdiagramm für M15 mit Service-Lebenslinien,parallelen Abfragen,Synchronisation,bedingtem atomarem Reservieren,asynchroner Benachrichtigung und Fehlerpfad. Begründen Sie die zulässige Reihenfolge.',
'''Client->Reservierung:reserve(kid);par{Reservierung->Katalog:preis(kid);Katalog-->Reservierung:preis}{Reservierung->Bestand:verfügbar(kid);Bestand-->Reservierung:bestand}. Joinbarriere:beide Antworten müssen vorliegen. alt[beide OK]{Reservierung->Bestand:reserveAtomar(kid);Bestand-->Reservierung:erfolgreich/ausverkauft;bei Erfolg Reservierung-->Client:201;Reservierung->>Benachrichtigung:vorgangErstellt(id)} else{Reservierung-->Client:Fehler}. Auch nach positiver Leseantwort kann atomare Reservierung wegen Konkurrenz scheitern;dann kein201 und keine Erfolgsbenachrichtigung. Benachrichtigung darf nach erfolgreicher Reservierung unabhängig vom Clientantwortzeitpunkt laufen. Asynchronität ist keine Umgehung der Vorbedingungen.''',
['Service-Lebenslinien und echtes Parallelfragment mit beiden Rückmeldungen/Joinbarriere fachlich korrekt modelliert.','Atomarer Reservierungsschritt,Erfolgs-/Fehleralternative und asynchrone Folgemeldung mit begründeter Ereignisordnung konsistent.'],['SEQ'])
add('5d0','Prüfen Sie M4 von1NFbis3NF und danach M10 auf1NF,2NF,3NF,BCNF. Bestimmen Sie die Kandidatenschlüssel vonZ aus FDs und zerlegen Sie ggf.verlustfrei inBCNF. Bewerten Sie auch Abhängigkeitserhaltung.',
'''M4:Listen sind nicht1NF,Entpacken ergibt E;Person/Buchung/KursZ entfernt partielle FDs(2NF),Team-Abtrennung die transitive FD(3NF),wie in der vollständigen Normalisierungslösung. Z:Kandidatenschlüssel(student,fach) und(student,dozent),denn dozent->fach und SF->D;student alleine,fach alleine,dozent alleine reichen nicht. Alle Attribute sind prim;atomare Werte->1NF;keine Nichtprimattribute->2NF und3NF(bei dozent->fach ist fach prim). BCNF verletzt:dozent ist kein Superschlüssel. Zerlegung D(dozent PK,fach),SD(student,dozent,PK(student,dozent)) ist verlustfrei,da Schnittdozent->D;beide BCNF. Daten D={(Dia,DB),(Wes,Web)},SD={(Ada,Dia),(Ben,Dia),(Ada,Wes)}. SF->D ist nicht in einer Teilrelation lokal prüfbar;Abhängigkeitserhaltung geht verloren und benötigt zusätzliche Prüfung. Nicht behaupten,jede verlustfreie BCNF-Zerlegung erhalte alle FDs.''',
['M4-Schritte1NF–3NF korrekt begründet und Z-Schlüssel/1NF–3NF aus vollständigen FDs beurteilt.','BCNF-Verstoß und verlustfreie BCNF-Zerlegung mit konkreten Daten/Schlüsseln korrekt,Verlust der lokalen Abhängigkeitserhaltung erkannt.'],['NORM','BCNF'])
add('98f','Wählen Sie mit M11 Indexarten für Punktlookup und Bereichsfilter preis<=20. Berechnen/vergleichen Sie modellierte Lese-/Schreib-/Speicherkosten und begründen Sie eine passende Wahl bei1000Schreibungen. Nennen Sie die Grenze dieser Abschätzung.',
'''Punktlookup:Vollscan10000,B-Baum14+1=15,Hash1+1=2;Hash für reine Gleichheit am günstigsten unter Vorgabe. Bereich preis<=20:B-Baum geeignet,Hash laut Modell ungeeignet. Für100Lookup-FK-Probes:100*14+10000=11400 plus Kursvollscan10000 ergibt21400;früher Hash-Join:1000100+10000=1010100. Je zusätzlichem Index1000*2=2000Schreibkosten,Speicher B-Baum200KiB,Hash180KiB. Lesen spart hier viel,aber nur einen Index für die tatsächlich häufige Abfrage begründet wählen;bei dominanten Bereichsfiltern B-Baum,bei ausschließlich Punktzugriff Hash möglich. Das Lehrmodell berücksichtigt keine Cache-/Selektivitäts-/Optimierer-/Hardwaredetails,ist keine gemessene Geschwindigkeit.''',
['Passende B-Baum-/Hash-Wahl für Gleichheit und Bereich mit korrekter Kostenmodell-Anwendung.','Lesevorteile gegen zusätzliche Schreib-/Speicherkosten abgewogen und Grenzen der Schätzung ausdrücklich begründet.'],['COST'])
add('5b9','Erläutern Sie ACID und ordnen Sie alle drei M13-Abläufe einer Anomalie zu. Vergleichen Sie die vier vorgegebenen Isolation-Level;entwerfen Sie einen konsistenten Reservierungsablauf mit rowcount und Fehlerversuch. Keine SQLite-Isolationseigenschaft aus der Standardkarte ableiten.',
'''Atomicity:ganze Reservierung oder rollback;Consistency:frei>=0 und korrekte Zuordnung;Isolation:konkurrierende Abläufe dürfen das Resultat nicht verfälschen;Durability:commit übersteht zugesicherten Neustart. L ist lost update/Überbuchungsbehauptung:beide lesen1 und schreiben0,keine zwei Plätze vorhanden. D ist dirty read eines später zurückgerollten Werts;N nonrepeatable read. RU kann dirty erlauben,RC verhindert dirty,RR zusätzlich nonrepeatable,Serializable serielle Äquivalenz mit möglichem Konfliktabbruch;Phantome beiRR nach Vorgabe nicht generell ausgeschlossen. Sicherer begrenzter Ablauf:BEGIN;UPDATE Bestand SET frei=frei-1 WHERE kid=? AND frei>0;rowcount1->commit/Erfolg,0->rollback/ausverkauft;zweiter Versuch bei0 darf keinen Erfolg melden. Bei Serialisierungsfehler ganze Transaktion nach Vertrag wiederholen oder abbrechen. Nur commit() ohne atomare Bedingung löst L nicht.''',
['ACID mit Fallbezug und alle drei Anomalien korrekt erläutert.','Isolation-Level nach Karte unterschieden und konsistenter atomarer Reservierungsvertrag mit Erfolgs-/Fehlerprüfung begründet.'],['TRANS'])
add('a49','Setzen Sie M5 durch eine View und Rollenbefehle um. Zeigen Sie eine zulässige öffentliche SELECT-Abfrage und zwei konkret verbotene Operationen;erläutern Sie die Grenze einer Sicht,wenn daneben Basistabellenrechte bestehen.',
'''CREATE VIEW KursAuskunft AS SELECT kid,titel,preis FROM Kurs;
GRANT SELECT ON KursAuskunft TO auskunft;
REVOKE SELECT ON Person FROM auskunft;
GRANT SELECT,INSERT ON Buchung TO anmeldedienst;
Erlaubt auskunft:SELECT kid,titel,preis FROM KursAuskunft;verboten:SELECT email FROM Kontakt;UPDATE Kurs SET preis=0. Explizite Matrix:auskunft{KursAuskunft:SELECT},anmeldedienst{Buchung:SELECT,INSERT},sonstkeine. View versteckt Spalten nur,wenn die Rolle keinen direkten Basiszugriff hat;der irrtümliche Person-Zugriff muss entzogen werden. Keine Behauptung,dass die DCL-Befehle in SQLite liefen.''',
['View mit minimalen Spalten und korrekte Rollen-/Entzugsbefehle tatsächlich formuliert.','Erlaubte/verbotene Operationen und Grenze bei parallelem Basisrecht fachlich korrekt geprüft.'],['DB','ROLES'])
add('c739','Begründen Sie für M11 die Join-Reihenfolge und einen passenden Index für die Abfrage der Buchungen günstiger Kurse. Vergleichen Sie ungefiltertes Produkt,frühe Selektion+Hash-Join und Indexzugriff;erläutern Sie,warum gleiche Ergebnismenge eine notwendige Voraussetzung der Optimierung ist.',
'''Kurs früh aufpreis<=20 filtern,erst dann mit Buchung auf kid joinen;Index Buchung(kid) hilft den100 passenden Kurs-IDs. Ungefiltertes Produkt10^10Paare,gefiltertes Produkt10^8;Hash-Join verarbeitet1000100 Eingabezeilen plus Kursvollscan10000=1010100 Modellkosten;Indexplan11400+10000=21400. Nicht bedingungslos jeden Join nach beliebigem Attribut ersetzen;Status-/weitere fachliche Filter bleiben erhalten. Bei vielen Treffern können sequentielle/Hash-Pläne günstiger werden;hier gilt die gegebene Selektivität. Ergebnisprüfung und EXPLAIN bei echter DB ergänzen die Modellbegründung.''',
['Frühe Selektion,Join-Reihenfolge und Indexgebrauch anhand der konkreten Selektivität fachlich begründet.','Alternative Plankosten korrekt verglichen und Ergebnisäquivalenz/Modellgrenzen ausdrücklich beachtet.'],['COST'])
add('303','Entwerfen Sie eine kleine RESTful API für M2:Kursliste,einzelner Kurs,neue Buchung und Änderung eines eigenen Buchungsstatus. Geben Sie Method/Pfad,Parameter,Statuscodes,Autorisierung und Service/Repository-Grenze an. Zeigen Sie positiven und fremden Zugriff;DB-Zugang darf nicht im Browser liegen.',
'''GET /kurse?maxPreis=30->200 Liste,GET /kurse/10->200 bzw404;POST /buchungen mit {kid:40}->201 und Location:/buchungen/1/40,bei Doppelbuchung409;PATCH /buchungen/1/40 mit {status:'storniert'}->200 bzw204,bei anderem Nutzer403. pid stammt aus Sitzung;Server prüft Pfadpid=Sessionpid,status-Enum,Kurs und Geschäftsbedingung. HTTP400 für ungültiges Format. Controller validiert/übersetzt HTTP,Service prüft Rechte/Invarianten,Repository kapselt parametrisierte SQL-Verbindung/commit. JSON enthält keine Kontaktadressen/DB-Secrets. Positiv Session1/PATCH1/40,nach vorhandener Buchung;negativ Session2/PATCH1/40->403 ohne DB-Änderung. Ressourcen-/Methodenvarianten sind zulässig,wenn Idempotenz und Semantik stimmen.''',
['Konsistente ressourcenbezogene API mit Methoden,Parametern,Antworten/Statuscodes und Beispielzugriffen modelliert.','Datenzugriff hinter Service/Repository gekapselt und Session-/Objektberechtigung vor Änderung konkret abgesichert.'],['DB','WEB'])
add('0e0','Implementieren/präzisieren Sie für maxPreis,kid,titel Client- UND Servervalidierung nach M6;zeigen Sie sichere SQL-Parameter und HTML-Ausgabe. Prüfen Sie 5000-Ziffern,Unicode-Ziffern,-1,doppelte Werte,titel=<script>x</script>,SQL-Injectiontext. Begründen Sie,warum Validierung/kontextspezifisches Escaping verschiedene Aufgaben sind.',
'''Client:number min/max required,kid-Bereich,titel maxlength80. Server akzeptiert genau erwartete Namen und genau einen Wert;prüft Länge vor int(),ASCII[0-9]+,Bereich;Titel1..80Zeichen. 5000Ziffern,Unicode-Ziffern,-1,doppelte Parameter oder SQL-Code im numeric Feld->400;Clientumgehung ändert dies nicht. Titel'<script>x</script>' darf als normaler Titeltext gespeichert werden,wenn Längenvorgabe erfüllt;parametrisiertes UPDATE bindet ihn als Daten. Ausgabe html.escape(...,quote=True) zeigt &lt;script&gt;x&lt;/script&gt;,führt kein Skript aus. Frei eingegebener Titel x\' OR1=1 bleibt gebundener Wert und keine SQL-Struktur. HTML-Escaping ist für HTML-Text/zitierte Attribute,kein universeller JavaScript-/SQL-Sanitizer. Keine aggressiven Löschregeln nötig;fachliche Validierung und Kontextkodierung ergänzen sich.''',
['Client- und unabhängige Servervalidierung inklusive vorangestellter Längenbegrenzung und negativer Fälle konkret umgesetzt.','Parametrisierte SQL-Werte und kontextspezifische HTML-Kodierung mindern die konkret gezeigten Angriffe,harmlosen Text nicht unnötig verboten.'],['WEB'])
add('955','Entwerfen Sie sichere Handhabung einer gegebenen Sitzung mit Token und Cookie für /buchen. Gegeben:Server besitzt Sessionmap,HTTPS wird bereitgestellt,Token kann mit sicherem Zufall erzeugt und serverseitig gehasht gespeichert werden. Beschreiben Sie Login-Rotation,Ablauf,Logout,CSRF und Cookieattribute,prüfen Sie zwei Nutzer. Kein OAuth-Framework implementieren.',
'''Cookie trägt nur unvorhersehbare Session-ID,serverseitige Map bindet pid,expiry,csrfHash. Set-Cookie: sid=<zufallswert>;Secure;HttpOnly;SameSite=Lax;Path=/;Lebenszeit nach Vertrag. Nach Login/Rechtewechsel neue Session-ID,alte ungültig(Fixation);Ablauf und Logout entfernen serverseitige Berechtigung,nicht bloß Cookie im Browser. TLS schützt Transport,HttpOnly JavaScriptzugriff,SameSite reduziert Cross-Site-Senden;zusätzlich CSRF-Token für Zustandsschreiben. Token keine URL/Logs,fehlendes/abgelaufenes Token->401,falscher CSRF403,fremde Objektpid403. NutzerA mit Sessionpid1 darf nur1 buchen,NutzerBpid2 erhält durch kopierte Formularpid1 keine Rechte. Sessionkennung ist kein dauerhaftes Lernendenprofil;Tests nutzen fiktive Tokens.''',
['Cookie/Session/Token-Lebenszyklus mit Rotation,Ablauf,Logout und passenden Schutzattributen konsistent beschrieben.','Sessionbindung,CSRF-/Objektprüfung und Zwei-Nutzer-Negativfälle verhindern die konkret geforderten Verwechslungen.'],['WEB'])
add('1a3','Begründen Sie für dieses Webszenario Caching UND Asynchronität:Katalogtitel ändern selten,Buchungsplätze ändern häufig,Benachrichtigung dauert2s,Reservierung darf erst nach bestätigter atomarer Platzvergabe als Erfolg erscheinen. Gegeben ETag/If-None-Match/304 und Queue mit idempotentem Jobschlüssel. Entwerfen Sie Ablauf,Invalidierung und Fehlerverhalten.',
'''Öffentlichen Katalog nach Version/ETag cachen,GET mit If-None-Match liefert304 bei unverändertem Inhalt;Titel-/Preisänderung erhöht Version/invalidiert Cache. Personenbezogene Buchungen nicht öffentlich cachen;freie Plätze nicht als verbindliche Reservierung aus altem Cache behandeln. Platzvergabe synchron atomar bestätigen,dann Job(id=VorgangID) für Benachrichtigung in Queue;Worker kann2s brauchen,Retry mit idempotentem Schlüssel verhindert doppelte Nachricht. Erfolgsantwort hängt vom Reservierungsergebnis ab,nicht vom Mailversand;Jobfehler protokollieren/wiederholen. Asynchrone parallele Reads können Anzeige beschleunigen,ersetzen aber keine Bestandsprüfung. Tradeoff:Katalogcache spart Reads/Netz,zeigt bis Invalidierung möglicherweise alte Titel;Queue erhöht Betriebsaufwand.''',
['Sinnvolles Caching mit konkretem Schlüssel/Validierung/Invalidierung und Schutz privater bzw.fachlich zeitkritischer Daten begründet.','Asynchrone Verarbeitung mit korrekter Erfolgsgrenze,Retry/Idempotenz und nachvollziehbarer Leistungs-/Konsistenzabwägung entworfen.'])
add('729','Verankern Sie Datenschutz in einem Systementwurf für M7:Datenspeicher-/Zwecktrennung,Voreinstellungen,Datenminimierung,Fristen,Löschung/Widerruf und überprüfbarer Entwurf. Geben Sie konkrete Felder/Flows an,statt nur Prinzipien zu nennen.',
'''ContractDB speichert pid,kid,status für Vertragsabwicklung;separater optionaler Marketingstore speichert nur consentId,freigegebene Zwecke und erforderliche Klickkategorien statt Kontaktdaten-Vollkopie. Voreinstellung Werbungaus,Profilprivat,kein genauer Standort. Erst aktive getrennte Einwilligung aktiviert Marketingflow;consentRecord enthält Zweck,Textversion,Zeitpunkt,Nachweis und Widerruf. Widerrufsereignis sperrt neue Verarbeitung und löscht zugehörige optionale Profile nach begründetem Ablauf;notwendige Vertragsbelege bleiben zweckgebunden und nur so lange wie rechtlich nötig,keine erfundene allgemeine Tagesfrist. Rollen/Logs beschränken Zugriff. Prüffälle:ohne Einwilligung kein Export;Widerruf stoppt Export;Vertragsbuchung funktioniert dennoch. Design setzt Art.5,7,25 in Tabellen/Flows/Defaults um;Pseudonymisierung allein macht Daten nicht anonym.''',
['Konkrete datensparsame Architektur mit Zwecktrennung,schützenden Defaults und begründeten Fristen gestaltet.','Einwilligungs-/Widerrufs-/Löschflow samt Prüfbeispielen und fortbestehenden Vertragszwecken konsistent im Design verankert.'],['LAW'])
add('2f5','Klassifizieren Sie alle fünf M16-Fälle nach der gelieferten OWASP-Karte. Zeichnen/beschreiben Sie Trust Boundaries und priorisieren Sie zwei Risiken mit Eintrittswahrscheinlichkeit/Auswirkung anhand konkreter Annahmen;geben Sie Maßnahmen und Prüffälle an.',
'''Fremde pid->BrokenAccessControl;verkettetes SQL->Injection;Cookie nachLogout->AuthenticationFailures;Debugdaten->SecurityMisconfiguration;unverschlüsselter Passworttransport->CryptographicFailures. Browser->Server trennt untrusted Eingaben vom Authkontext,Server->DB trennt Dienstrolle/parametrisierte Datenzugriffe. Hohe Priorität z.B.fremde Kontaktadresse(angemeldeter Nutzer kann IDs raten,hoher Datenschutzschaden) und Injection(offener Texteingang,hohe Änderungsgefahr). Maßnahmen Objektprüfung+negativer Zwei-Nutzer-Test,parametrisierte Queries+Quote-Injectiontest;außerdem serverseitiger Sessionentzug,Debugaus,TLS. Priorität ist mit Annahmen begründet,keine erfundene gemessene Risikowahrscheinlichkeit.''',
['Alle fünf konkreten Bedrohungen zutreffend nach vorgegebener OWASP-Karte und Vertrauensgrenzen klassifiziert.','Zwei begründete Risikoprioritäten mit passenden Maßnahmen und überprüfbaren negativen Fällen entwickelt.'],['THREAT'])
add('f029','Ordnen Sie drei Zwecke zu:schnelle Verschlüsselung eines großen Backups,Schlüsselaustausch für einen unbekannten Empfänger,Nachweis der Herkunft/Unverändertheit eines veröffentlichten Angebots. Beschreiben Sie symmetrische/asymmetrische Verfahren und digitale Signatur einschließlich Schlüsselrollen und Grenzen. Kryptographie muss nicht selbst implementiert werden.',
'''Großes Backup:symmetrischer Schlüssel verschlüsselt/entschlüsselt effizient,z.B.authentifizierte Verschlüsselung;Schlüssel getrennt sicher aufbewahren. Austausch/hybrider Transport:Empfängerpublickey schützt zufälligen symmetrischen Sitzungsschlüssel,nur Empfängerprivatekey öffnet;Serveridentität/Publickey müssen vertrauenswürdig geprüft sein. Signatur:Autor signiert mit privatekey,Prüfer verifiziert mit publickey;authentifiziert Herkunft/Integrität bei vertrauenswürdig zugeordnetem Schlüssel,verbirgt Inhalt nicht. Hash allein beweist keine Urheberschaft;Verschlüsselung allein keine Identität des Absenders. Geheimer Schlüssel darf nicht im gleichen öffentlichen Backup liegen;keine eigene unsichere Kryptobibliothek nötig.''',
['Symmetrische/asymmetrische Verfahren den Zwecken korrekt mit Schlüsselrollen zugeordnet und hybrides Prinzip erklärt.','Digitale Signatur hinsichtlich privatem Signieren/öffentlichem Prüfen,Herkunft/Integrität und fehlender Vertraulichkeit korrekt eingeordnet.'])
add('b2d','Formulieren Sie für M3 dieselbe sichere Abfrage im Tupel- UND Domänenkalkül:Farben der R-Tupel,deren a in V mit b20 verbunden ist. Variablen/Domänen benennen und vollständiges Ergebnis angeben;erläutern Sie Bereichsbeschränkung.',
'''Tupelkalkül:{t.x | R(t) AND exists v(V(v) AND v.a=t.a AND v.b=20)}. Domänenkalkül:{<x> | exists a(exists b(R(a,x) AND V(a,b) AND b=20))}. a,b sind IDs,x Text;alle ausgegebenen Werte stammen aus R,alle übrigen Variablen aus positiven Relationsatomen. Daher sichere Bereichsbeschränkung;kein unbeschränktes Komplement über alle denkbaren Texte. Ergebnis(x)={('rot'),('blau')}. Gleichwertige benannte Ergebnistupel sind erlaubt,aber beide Kalkülformen müssen erkennbar sein.''',
['Sicheren Tupelkalkül mit korrekter Quantifikation/Join-/Selektionsbedingung angewandt.','Äquivalenten Domänenkalkül mit Bereichsbeschränkung und vollständigem Ergebnis angewandt.'],['ALG'])
add('c499','Formen Sie pi_pid,titel(sigma_preis<=20(Person JOIN_pid Buchung JOIN_kid Kurs)) äquivalent um:M2-Attribute eindeutig qualifiziert,kein Statusfilter verlangt. Ziehen Sie Selektion und nötige Projektionen vor;vergleichen Sie mit M11 Produkt-/Hash-Kosten und erklären Sie,welche Attribute Sie für Joins behalten müssen.',
'''pi_P.pid,K.titel(Person P JOIN_P.pid=B.pid Buchung B JOIN_B.kid=K.kid sigma_K.preis<=20(Kurs K)). Nach Pushdown:pi_pid,titel(pi_pid(Person) JOIN_pi.pid=B.pid pi_pid,kid(Buchung) JOIN_B.kid=K.kid pi_kid,titel(sigma_preis<=20(Kurs))). pid und kid als Joinattribute dürfen vorher nicht entfernt werden;preis erst nach Selektion. Beide liefern in M2 {(1,Fotobasis),(2,Fotobasis),(3,Fotobasis),(5,Datenschutz-Werkstatt),(2,Datenschutz-Werkstatt)};stornierte zählen,weil kein Statusfilter gegeben.10^10 ungefilterte Produktpaare versus10^8 nach Kursselektion;Hashkosten1010100 mit Kursvollscan nach M11. Projektionen senken Tupelbreite,im gegebenen n+m-Zeilenmodell nicht automatisch Zeilenzahl;keine erfundene Prozentbeschleunigung.''',
['Äquivalente Selektion-/Projektionsumformung mit erhaltenen Joinattributen und korrekter Mengenbedeutung ausgeführt.','Konkrete Resultatäquivalenz und Kosten-/Tupelbreiteneffekt anhand des Lehrmodells fachlich richtig geschätzt.'],['DB','COST'])
add('fbc','Vergleichen Sie für beide M18-Arbeitslasten relationale,Document- und WideColumn-Organisation. Erklären Sie mindestens eine echte relationale Grenze aus der Last und wählen Sie begründet;zeigen Sie je Datenform/Schlüssel und einen Tradeoff. Große Datenmenge allein ist kein Gegenbeweis gegen Relationen.',
'''Buchung relational:PK(pid,kid),FKs/Constraints und atomare Platzvergabe passen,flexible Joins bleiben möglich. Klicks können als Dokument{event,kid,extras} variable Ereignisfelder bündeln oder WideColumn(tag,kid)->zeitgestempelte Ereignisse für bekannte Tages-/Kursabfragen partitionieren. Relationale Grenze in dieser gegebenen Last:variable Eventfelder erzwingen viele optionale Spalten/Zusatztabellen oder JSON und häufige Schemaverarbeitung;verteilte Joins/übergreifende Transaktionen über100Millionen Ereignisse können teuren Netzwerk-/Koordinationsaufwand erzeugen. Das ist eine Last-/Entwurfsgrenze,keine prinzipielle Unmöglichkeit von relationalem Sharding/JSON. WideColumn günstig für vorab bekannte Partitionabfragen,aber neue Querverknüpfungen und globale Transaktionsregeln schwieriger;Dokumentmodell flexibel,aber eingebettete Duplikate brauchen Aktualisierungskonsistenz. Wahl:Verträge relational,Klickanalyse z.B.WideColumn nach(tag,kid),mit Hotspot-/Retentionsplanung. Keine NoSQL-Geschwindigkeitsgarantie.''',
['Grenzen relationaler Organisation konkret aus variablen/verteilt umfangreichen Klicklasten erklärt,ohne pauschale Unmöglichkeitsbehauptung.','Document-/WideColumn-Alternativen mit Daten-/Schlüsselbeispiel und begründeter Wahl/Tradeoffs für beide Arbeitslasten eingeordnet.'],['LARGE'])
add('e94','Führen Sie Map,Shuffle und Reduce für M18 aus:Zählung der Klickereignisse je Kurs. Geben Sie alle Map-Ausgaben,Gruppen,Endzählungen an,erklären Sie parallele Schritte und Invarianz bei anderer Partitionierung;keine Statechartleistung ist Teil dieser Aufgabe.',
'''MapP1=[(10,1),(20,1),(10,1)],MapP2=[(30,1),(20,1),(10,1)]. Shuffle:{10:[1,1,1],20:[1,1],30:[1]};Reduce:{10:3,20:2,30:1}. Maps können unabhängig pro Partition laufen,Reduce unabhängig je Schlüssel nach Gruppierung. Summe ist assoziativ/kommutativ,deshalb andere Partitionierung gleicher genau einmal verarbeiteter Ereignisse dieselben Counts. Doppelte Wiederholung ohne Deduplizierung wäre keine gleiche Eingabemenge. Kurse40/50 haben hier kein Event und erscheinen in diesem Reduce nicht;M17-Ranking ergänzt0. Große Datenmengen werden durch verteilte Teilverarbeitung bewältigt,Shuffle kann Netzwerkengpass sein.''',
['Alle konkreten Map-/Shuffle-/Reduce-Zwischenschritte und Counts korrekt ausgeführt.','Parallelverarbeitung sowie Partitionsinvarianz unter genau-einmal-Eingabe und Grenze des Shuffles erklärt.'],['LARGE'])
